use anyhow :: { Context , Result } ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: io :: { BufRead , BufReader } ; use log :: info ; # [doc = " Fast count lines in a file"] fn fast_count_lines (path : & Path) -> Result < usize > { if ! path . exists () { return Ok (0) ; } let content = fs :: read_to_string (path) . context (format ! ("Failed to read input file: {}" , path . display ())) ? ; Ok (content . lines () . count ()) }